previewCss:
.darma-loader-darma-b11-camera-shutter { --accent: var(--loader-color, #0ea5e9); --accent-2: var(--loader-secondary-color, #334155); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; border-radius: 50%; overflow: hidden; background: radial-gradient(circle, #0b0b0b 28%, #1c1c1c); }
.darma-loader-darma-b11-camera-shutter span { position: absolute; inset: 0; background: linear-gradient(140deg, var(--accent), var(--accent-2)); clip-path: polygon(50% 50%, 100% 12%, 100% 52%); transform-origin: 50% 50%; animation: darma-loader-darma-b11-camera-shutter-iris calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b11-camera-shutter span:nth-child(1) { transform: rotate(0deg); }
.darma-loader-darma-b11-camera-shutter span:nth-child(2) { transform: rotate(60deg); }
.darma-loader-darma-b11-camera-shutter span:nth-child(3) { transform: rotate(120deg); }
.darma-loader-darma-b11-camera-shutter span:nth-child(4) { transform: rotate(180deg); }
.darma-loader-darma-b11-camera-shutter span:nth-child(5) { transform: rotate(240deg); }
.darma-loader-darma-b11-camera-shutter span:nth-child(6) { transform: rotate(300deg); }
@keyframes darma-loader-darma-b11-camera-shutter-iris { 0%, 100% { rotate: 0deg; } 50% { rotate: -48deg; } }

